def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)

    axis = None
    for r, row in enumerate(grid):
        if all(value == 2 for value in row):
            axis = ("h", r)
            break
    if axis is None:
        for c in range(w):
            if all(grid[r][c] == 2 for r in range(h)):
                axis = ("v", c)
                break
    if axis is None:
        return out

    points = [(r, c) for r in range(h) for c in range(w)
              if grid[r][c] != background and grid[r][c] != 2]
    if not points:
        return out

    direction, pos = axis
    if direction == "v":
        left = min(c for r, c in points)
        right = max(c for r, c in points)
        if left > pos:
            target = right + 1
        elif right < pos:
            target = left - 1
        else:
            return out
        if 0 <= target < w:
            for r in range(h):
                out[r][target] = 8
    else:
        top = min(r for r, c in points)
        bottom = max(r for r, c in points)
        if top > pos:
            target = bottom + 1
        elif bottom < pos:
            target = top - 1
        else:
            return out
        if 0 <= target < h:
            out[target] = [8] * w
    return out

